/**
 * Content-pack types and shared constants.
 *
 * These live in `src/lib/` because the pack is generated by Node scripts AND
 * consumed by the browser bundle. They must stay dependency-free and
 * dependency-light so both runtimes agree on the shape of the data.
 *
 * (The `shared/` directory is reserved for code that also runs inside Supabase
 * Edge Functions — the pack itself does not need to go there.)
 */

/** Provenance of a pack entry. Drives the "unverified" badge in the UI. */
export const PACK_VERSION = '0.2.0'

/** Placeholders a template or phrase may use. Enforced by tests/pack.test.ts. */
export const ALLOWED_PLACEHOLDERS = [
  'zone',
  'shelter',
  'distance',
  'until',
  'level',
  'hazard',
  'direction',
  'time',
  'place',
  'name',
] as const

export type Placeholder = (typeof ALLOWED_PLACEHOLDERS)[number]

// ---------------------------------------------------------------------------
// places.json
// ---------------------------------------------------------------------------

/**
 * OSM amenity classes we treat as safety-relevant.
 * `shelterCandidate` is deliberately NOT an official shelter — it is a building
 * that might be usable. It always carries `verified: false`.
 */
export const PLACE_TYPES = [
  'hospital',
  'clinic',
  'police',
  'pharmacy',
  'fire_station',
  'shelter_candidate',
] as const

export type PlaceType = (typeof PLACE_TYPES)[number]

/** How a place should behave when routing or showing it. */
export const PLACE_ROLES: Record<PlaceType, 'shelter' | 'medical' | 'safety' | 'supply'> = {
  hospital: 'medical',
  clinic: 'medical',
  pharmacy: 'supply',
  police: 'safety',
  fire_station: 'safety',
  shelter_candidate: 'shelter',
}

export interface Place {
  /** Stable id: `<type>-<osm id>`, e.g. `hospital-123456`. */
  readonly id: string
  readonly type: PlaceType
  /** `null` when OSM has no name — never invent one. */
  readonly name: string | null
  readonly lat: number
  readonly lon: number
  /** Where the record came from. Always `osm` or `sample` in this pack. */
  readonly source: 'osm' | 'sample'
  /** Always `false` for machine-extracted data (engineering rule 7). */
  readonly verified: false
  /** Human notes: OSM tags we kept, and what still needs checking. */
  readonly notes: string
  /** `true` only for a hand-written fallback file so the UI can warn. */
  readonly sample?: boolean
  /** Present when the OSM way is a polygon centre; useful for rendering. */
  readonly bbox?: readonly [number, number, number, number]
}

export interface PlacesFile {
  readonly _meta: PackMeta
  readonly regionId: string
  readonly count: number
  readonly places: readonly Place[]
}

// ---------------------------------------------------------------------------
// roads.json
// ---------------------------------------------------------------------------

/** Bit flags packed into a single byte per edge to keep the graph compact. */
export const EDGE_FLAG = {
  /** Motor vehicles allowed (highway=primary/secondary/tertiary/residential/...). */
  DRIVABLE: 1,
  /** Pedestrians allowed (footway, path, steps, living_street, cycleway). */
  WALKABLE: 2,
  /** Crosses or runs beside a watercourse / flood-prone way. */
  WATER: 4,
  /** Bridge/tunnel/crossing — extra caution for flood routing. */
  CROSSING: 8,
} as const

export const EDGE_FLAG_NAMES: Record<number, keyof typeof EDGE_FLAG> = {
  1: 'DRIVABLE',
  2: 'WALKABLE',
  4: 'WATER',
  8: 'CROSSING',
}

/** Coordinate precision kept in the shipped graph (~1.1 m at the equator). */
export const COORD_DECIMALS = 4

/**
 * Compact tuple encodings — what actually ships in roads.json.
 *
 * Object-per-node JSON cost ~45% more bytes than tuples, which pushed the
 * graph over the 1.5 MB download budget. Tuples are also how the brief
 * describes the format. Use `readRoadNode`/`readRoadEdge` in app code to get
 * the readable shape back.
 */
export type RoadNodeTuple = readonly [id: number, lat: number, lon: number]
export type RoadEdgeTuple = readonly [from: number, to: number, lengthMetres: number, flags: number]

export interface RoadNode {
  readonly id: number
  readonly lat: number
  readonly lon: number
}

export interface RoadEdge {
  readonly from: number
  readonly to: number
  /** Metres, rounded to the nearest metre. */
  readonly lengthMetres: number
  /** Bitfield of EDGE_FLAG. */
  readonly flags: number
}

/** Turn a packed node tuple back into a readable object. */
export function readRoadNode(tuple: RoadNodeTuple): RoadNode {
  return { id: tuple[0], lat: tuple[1], lon: tuple[2] }
}

/** Turn a packed edge tuple back into a readable object. */
export function readRoadEdge(tuple: RoadEdgeTuple): RoadEdge {
  return { from: tuple[0], to: tuple[1], lengthMetres: tuple[2], flags: tuple[3] }
}

export interface RoadsFile {
  readonly _meta: PackMeta
  readonly regionId: string
  readonly nodeCount: number
  readonly edgeCount: number
  readonly nodes: readonly RoadNodeTuple[]
  readonly edges: readonly RoadEdgeTuple[]
  /** True only for the hand-written offline fallback grid. */
  readonly sample?: boolean
}

// ---------------------------------------------------------------------------
// zones.geojson
// ---------------------------------------------------------------------------

export interface ZoneProperties {
  /** `Z1`..`Zn` — these ids are what signed packets reference. */
  readonly id: string
  readonly name: string
  /** Areas that flood first, or sit lowest. Drives default rendering. */
  readonly floodProne: boolean
  /** Why this polygon exists, in plain words for a non-expert. */
  readonly note: string
  /** Always a hand-drawn, approximate value for now (engineering rule 7). */
  readonly source: string
  readonly verified: false
}

export interface ZoneFeature {
  readonly type: 'Feature'
  readonly id: string
  readonly properties: ZoneProperties
  readonly geometry: {
    readonly type: 'Polygon'
    /**
     * GeoJSON polygon coordinates: an array of linear rings, each ring an array
     * of [lon, lat] positions. The outer ring is closed (first === last).
     */
    readonly coordinates: readonly (readonly (readonly [number, number])[])[]
  }
}

export interface ZonesGeoJson {
  readonly type: 'FeatureCollection'
  readonly features: readonly ZoneFeature[]
}

// ---------------------------------------------------------------------------
// kb/<locale>.json
// ---------------------------------------------------------------------------

export interface KbChunk {
  readonly id: string
  readonly title: string
  /** Search terms, lowercase. Feeds MiniSearch in M10. */
  readonly tags: readonly string[]
  /** Numbered actions, imperative and short. */
  readonly steps: readonly string[]
  /** `critical` → always escalate, `urgent`, `routine`. */
  readonly severity: 'critical' | 'urgent' | 'routine'
  /** True when this situation needs professional help now. */
  readonly escalate: boolean
  /** Named authority the guidance is based on. */
  readonly source: string
  /**
   * Medical content is ALWAYS unverified until a clinician signs it off.
   * See TODO_VERIFY.md.
   */
  readonly verified: false
}

export interface DecisionTree {
  readonly id: string
  /** Questions use placeholders-free, plain text. */
  readonly question: string
  readonly options: readonly DecisionOption[]
  /**
   * Shown when a question has no options, or as the result of an option with
   * `next: null`.
   */
  readonly terminalSteps?: readonly string[]
  /** `true` when the terminal state means "get professional help now". */
  readonly terminalEscalates?: boolean
}

export interface DecisionOption {
  readonly label: string
  /** Another node id, `null` for a terminal answer. */
  readonly next: string | null
}

export interface KbFile {
  readonly _meta: PackMeta
  readonly locale: string
  readonly chunks: readonly KbChunk[]
  readonly trees: readonly DecisionTree[]
}

// ---------------------------------------------------------------------------
// templates/<locale>.json
// ---------------------------------------------------------------------------

/** Hazard codes referenced by signed packets (M4). */
export const HAZARD_CODES = ['FL', 'CY', 'HT', 'WN', 'LS', 'AC'] as const
export type HazardCode = (typeof HAZARD_CODES)[number]

/** Severity levels 1..4. `AC` (all-clear) has no level. */
export const ALERT_LEVELS = [1, 2, 3, 4] as const
export type AlertLevel = (typeof ALERT_LEVELS)[number]

export interface AlertTemplate {
  /** `FL-3`, or `AC` for all-clear. */
  readonly id: string
  readonly hazard: HazardCode
  /** `null` for all-clear. */
  readonly level: AlertLevel | null
  /** One calm sentence. */
  readonly headline: string
  /** Up to 3 short imperative actions. */
  readonly steps: readonly string[]
  /** Words used when this template is rendered inside a drill banner. */
  readonly drillNote: string
}

export interface DrillText {
  readonly banner: string
  readonly bannerLong: string
  readonly disclaimer: string
}

export interface TemplatesFile {
  readonly _meta: PackMeta
  readonly locale: string
  readonly templates: readonly AlertTemplate[]
  readonly drill: DrillText
}

// ---------------------------------------------------------------------------
// phrases/<locale>.json
// ---------------------------------------------------------------------------

export const PHRASE_CATEGORIES = [
  'medical',
  'shelter',
  'transport',
  'food_water',
  'safety',
  'documents',
] as const

export type PhraseCategory = (typeof PHRASE_CATEGORIES)[number]

export interface Phrase {
  readonly id: string
  readonly category: PhraseCategory
  /** English text — the source the translator reads. */
  readonly text: string
  /** Optional Tamil transliteration, shown alongside the local script. */
  readonly phonetic?: string
  /** What a local should do when they read this. */
  readonly intent?: string
}

export interface PhrasesFile {
  readonly _meta: PackMeta
  readonly locale: string
  readonly categories: readonly { readonly id: PhraseCategory; readonly label: string }[]
  readonly phrases: readonly Phrase[]
}

// ---------------------------------------------------------------------------
// contacts.json
// ---------------------------------------------------------------------------

export interface EmergencyContact {
  readonly id: string
  /** The number as it should be dialled, digits only. */
  readonly number: string
  /** What it reaches. */
  readonly service: string
  /** Scope: national / state / international. */
  readonly scope: 'national' | 'state' | 'tourist'
  /** Short guidance on when to use it. */
  readonly note: string
  /**
   * ALWAYS false in this pack. Numbers are never guessed (rule 7) — see
   * TODO_VERIFY.md.
   */
  readonly verified: false
}

export interface Consulate {
  readonly id: string
  readonly country: string
  readonly name: string
  readonly city: string
  /** `null` when unknown — never guessed. */
  readonly phone: string | null
  readonly note: string
  readonly verified: false
}

export interface ContactsFile {
  readonly _meta: PackMeta
  readonly countryCode: string
  readonly emergency: readonly EmergencyContact[]
  readonly consulates: readonly Consulate[]
}

// ---------------------------------------------------------------------------
// manifest.json
// ---------------------------------------------------------------------------

export interface ManifestFileEntry {
  readonly path: string
  readonly bytes: number
  readonly sha256: string
}

export interface PackManifest {
  readonly version: string
  /** ISO 8601 build timestamp. */
  readonly builtAt: string
  readonly regionId: string
  readonly totalBytes: number
  readonly files: readonly ManifestFileEntry[]
}

// ---------------------------------------------------------------------------
// Shared meta block
// ---------------------------------------------------------------------------

export interface PackMeta {
  /** Pack schema version. */
  readonly packVersion: string
  /** ISO 8601 build timestamp. */
  readonly builtAt: string
  /** `true` when produced by machine translation and not human-reviewed. */
  readonly machineTranslated: boolean
  /** Always `false` until a qualified human signs the content off. */
  readonly reviewed: boolean
}

/** Placeholder token regex used by tests and the translator. */
export const PLACEHOLDER_RE = /\{(\w+)\}/g

/** Extract `{token}` names from a string, preserving order and duplicates. */
export function extractPlaceholders(input: string): string[] {
  const out: string[] = []
  for (const match of input.matchAll(PLACEHOLDER_RE)) {
    if (match[1] !== undefined) out.push(match[1])
  }
  return out
}
